namespace Lokad.Awk.Tests;

internal static partial class AwkGoldenCorpus
{
    // Native-selected GNU 5.2/5.4 profile survey in C.UTF-8/UTC.
    // Diagnostics use Lokad's stable prefix/exit 2. Known pending cases are excluded.
    private static IEnumerable<AwkGoldenCase> RegexProfileCompatibilityCases()
    {
        foreach (var row in RegexProfileRows)
        {
            var testCase = AwkGoldenCaseBuilder.Create(row.Name, row.Arguments, [])
                .WithStandardInput(row.Input).ExitsWith(row.Exit)
                .WithStdOut(row.StdOut).WithStdErr(row.StdErr).Build();
            yield return row.CompilationRejected ? CompilerDiagnostic(testCase) : testCase;
        }
    }

